/* VaR vs Expected Shortfall sur une distribution des pertes normale */
(function () {
  var svg = document.getElementById("var-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  // inverse de la normale standard (Acklam)
  function invNorm(p){
    var a=[-3.969683028665376e+01,2.209460984245205e+02,-2.759285104469687e+02,1.383577518672690e+02,-3.066479806614716e+01,2.506628277459239e+00];
    var b=[-5.447609879822406e+01,1.615858368580409e+02,-1.556989798598866e+02,6.680131188771972e+01,-1.328068155288572e+01];
    var c=[-7.784894002430293e-03,-3.223964580411365e-01,-2.400758277161838e+00,-2.549732539343734e+00,4.374664141464968e+00,2.938163982698783e+00];
    var d=[7.784695709041462e-03,3.224671290700398e-01,2.445134137142996e+00,3.754408661907416e+00];
    var pl=0.02425, ph=1-pl, q, r;
    if(p<pl){ q=Math.sqrt(-2*Math.log(p)); return (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1); }
    if(p<=ph){ q=p-0.5; r=q*q; return (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q/(((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1); }
    q=Math.sqrt(-2*Math.log(1-p)); return -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1);
  }
  function pdf(x,mu,sig){ var z=(x-mu)/sig; return Math.exp(-z*z/2)/(sig*Math.sqrt(2*Math.PI)); }
  function nfmt(x){ return (Math.round(x*100)/100).toFixed(2); }

  function draw(){
    var mu=v("vr-mu"), sig=v("vr-sig"), X=v("vr-x")/100;
    setT("vr-mu-o", mu.toFixed(0)); setT("vr-sig-o", sig.toFixed(0)); setT("vr-x-o", (X*100).toFixed(1)+"%");
    var z=invNorm(X);
    var VaR=mu+sig*z;
    var phi=Math.exp(-z*z/2)/Math.sqrt(2*Math.PI);
    var ES=mu+sig*phi/(1-X);
    setT("vr-var", nfmt(VaR)); setT("vr-es", nfmt(ES));
    setT("vr-ratio", (ES/VaR).toFixed(2)); setT("vr-tail", ((1-X)*100).toFixed(1)+"%");

    var W=520,H=300,L=16,R0=16,T0=16,B=34, pw=W-L-R0, ph=H-T0-B;
    var lo=mu-4*sig, hi=mu+4*sig;
    var pmax=pdf(mu,mu,sig);
    function px(x){ return L+(x-lo)/(hi-lo)*pw; }
    function py(d){ return T0+(1-d/(pmax*1.12))*ph; }

    var g="";
    // aire de queue (pertes > VaR) en rouge
    var d1="M "+px(VaR).toFixed(1)+","+(T0+ph).toFixed(1);
    for(var x=VaR;x<=hi;x+=(hi-VaR)/60){ d1+=" L "+px(x).toFixed(1)+","+py(pdf(x,mu,sig)).toFixed(1); }
    d1+=" L "+px(hi).toFixed(1)+","+(T0+ph).toFixed(1)+" Z";
    g+='<path d="'+d1+'" fill="var(--crimson)" opacity="0.22"/>';
    // courbe densité
    var d="";
    for(var i=0;i<=160;i++){ var xx=lo+(hi-lo)*i/160; d+=(i===0?"M ":" L ")+px(xx).toFixed(1)+","+py(pdf(xx,mu,sig)).toFixed(1); }
    g+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // ligne VaR (or)
    g+='<line x1="'+px(VaR).toFixed(1)+'" y1="'+T0+'" x2="'+px(VaR).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--gold)" stroke-width="2"/>';
    g+='<text class="tick" x="'+px(VaR).toFixed(1)+'" y="'+(T0+10)+'" text-anchor="middle" fill="var(--gold)">VaR</text>';
    // ligne ES (crimson)
    g+='<line x1="'+px(ES).toFixed(1)+'" y1="'+T0+'" x2="'+px(ES).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--crimson)" stroke-width="2" stroke-dasharray="5 3"/>';
    g+='<text class="tick" x="'+px(ES).toFixed(1)+'" y="'+(T0+10)+'" text-anchor="middle" fill="var(--crimson)">ES</text>';
    // axe X
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    var xl = al()==="en"?"loss L":(al()==="nl"?"verlies L":"perte L");
    g+='<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xl+'</text>';
    // graduations
    for(var t=-4;t<=4;t+=2){ var xv=mu+t*sig; g+='<text class="tick" x="'+px(xv).toFixed(1)+'" y="'+(T0+ph+14)+'" text-anchor="middle">'+xv.toFixed(0)+'</text>'; }
    // ligne zéro (référence)
    if(lo<0&&hi>0){ g+='<line x1="'+px(0).toFixed(1)+'" y1="'+(T0+ph-4)+'" x2="'+px(0).toFixed(1)+'" y2="'+(T0+ph+4)+'" stroke="var(--ink-mute)" stroke-width="1"/>'; }
    svg.innerHTML=g;
  }
  ["vr-mu","vr-sig","vr-x"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
